# Writes two small generated files of the manuscript: numbers/tab_stability.tex (Supplementary Table S6, from
# raw_summary_stability.csv of raw_derivation_summary.R) and numbers/raw_extra_numbers.tex (participants excluded from the
# random-sample prefix, the full exclusion list and the seed of the random order).
# Env: IN_DIR (folder with raw_summary_stability.csv), NUM_DIR (manuscript numbers folder), ORDER_FILE, EXCLUDED, R_MAX (default 1000).
suppressMessages(library(data.table))
this <- gsub("~+~", " ", sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1]), fixed = TRUE)
here <- if (is.na(this)) getwd() else dirname(normalizePath(this))
indir <- Sys.getenv("IN_DIR", getwd()); numdir <- Sys.getenv("NUM_DIR", getwd()); rmax <- as.integer(Sys.getenv("R_MAX", "1000"))
ordf <- Sys.getenv("ORDER_FILE", file.path(here, "analytic_random_order.tsv")); exf <- Sys.getenv("EXCLUDED", file.path(here, "excluded_seqn.txt"))
seed <- 20261016   # set.seed() value of make_random_order.R
# ---- Table S6: stability of the summaries after the first 500 and the first 1000 participants ----
st <- fread(file.path(indir, "raw_summary_stability.csv")); ser <- c(PAXPREDM = "\\texttt{PAXPREDM}", GGIR_SIB = "\\texttt{GGIR} SIB", GGIR_SPT = "\\texttt{GGIR} SPT", SWaN = "SWaN")
cell <- function(k, rr) { q <- st[stat == k & r == rr]; if (nrow(q) != 1) stop("missing ", k, " ", rr); f <- if (startsWith(k, "agree_")) 100 else 1   # agreement is stored as a proportion
  sprintf("%.1f (%.1f, %.1f)", f * q$est, f * q$lo, f * q$hi) }
rs <- sort(unique(st$r)); ns <- sapply(rs, function(rr) st[r == rr, n][1])
rows <- character()
for (blk in list(c("Mean SRI", "sri_", names(ser)), c("Mean difference to \\texttt{PAXPREDM}", "diff_", names(ser)[-1]), c("Transitions per day", "trans_", names(ser)), c("Agreement with \\texttt{PAXPREDM}, \\%", "agree_all_", names(ser)[-1])))
  for (s in blk[-(1:2)]) rows <- c(rows, sprintf("%s & %s & %s \\\\", blk[1], ser[[s]], paste(sapply(rs, function(rr) cell(paste0(blk[2], s), rr)), collapse = " & ")))
writeLines(c("% generated by make_extra_numbers.R from raw_summary_stability.csv; do not edit", "\\begin{tabular}{llcc}", "\\toprule",
             sprintf("Statistic & Series & %s \\\\", paste(sprintf("First %d ($n=%d$)", rs, ns), collapse = " & ")), "\\midrule", rows, "\\bottomrule", "\\end{tabular}"),
           file.path(numdir, "tab_stability.tex"))
# ---- excluded participants and seed ----
ord <- fread(ordf); ex <- as.integer(readLines(exf)); ex <- ex[!is.na(ex)]
pre <- ord[seqn %in% ex & rank <= rmax][order(rank), seqn]
writeLines(c("% generated by make_extra_numbers.R; numbers of the derivation sample",
             sprintf("\\newcommand{\\rawNexcl}{%d}", length(pre)), sprintf("\\newcommand{\\rawExclSeqn}{%s}", paste(pre, collapse = ", ")),
             sprintf("\\newcommand{\\rawNexclAll}{%d}", length(ex)), sprintf("\\newcommand{\\rawSeed}{%d}", seed)), file.path(numdir, "raw_extra_numbers.tex"))
cat("written:", file.path(numdir, "tab_stability.tex"), "and raw_extra_numbers.tex\n")
